$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
[IO.File]::WriteAllBytes((Join-Path $PWD 'docs/21.09.2026.01_Master_IP_Licence_Patentholder_to_PBK_RU_v3-1.docx'),[Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $PWD 'docs/01_Owner_MK_to_PBK_Master_IP_Licence_RU_20_oct_2026.docx'),[Convert]::FromBase64String(''))
foreach ($file in @('docs/01_Owner_MK_to_PBK_Master_IP_Licence_RU_20_oct_2026.docx','docs/21.09.2026.01_Master_IP_Licence_Patentholder_to_PBK_RU_v3-1.docx')) {
$zip = [IO.Compression.ZipFile]::OpenRead((Join-Path $PWD $file))
$reader = [IO.StreamReader]::new($zip.GetEntry('word/document.xml').Open())
[xml]$xml = $reader.ReadToEnd()
$ns = [Xml.XmlNamespaceManager]::new($xml.NameTable)
$ns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
$paras = @($xml.SelectNodes('//w:body//w:p',$ns) | ForEach-Object { ($_.SelectNodes('.//w:t',$ns) | ForEach-Object {$_.InnerText}) -join '' })
[IO.File]::WriteAllLines((Join-Path $PWD ($file+'.txt')), $paras)
Write-Output $file
$paras | Select-Object -Skip 100
$reader.Dispose()
$zip.Dispose()
}
